{
  "name": "todomvc-shakedown",
  "version": "0.1.0",
  "private": true,
  "scripts": {
    "test": "cucumber-js"
  },
  "devDependencies": {
    "@cucumber/cucumber": "*",
    "happy-dom": "*"
  },
  "dependencies": {
    "ajv": "^8.20.0",
    "todomvc-app-css": "^2.4.3",
    "todomvc-common": "^1.0.5"
  }
}

/* TodoMVC Vanilla JS
 *
 * Spec: assets/app-spec.md
 * Base markup: index.html
 * Storage key: todos-vanillajs
 */
(function () {
  'use strict';

  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;
  var STORAGE_KEY = 'todos-vanillajs';

  // ── Helpers ───────────────────────────────────────────────────────────

  function qs(sel, ctx) { return (ctx || document).querySelector(sel); }

  function qsa(sel, ctx) { return (ctx || document).querySelectorAll(sel); }

  function pluralize(count) { return count === 1 ? 'item' : 'items'; }

  function getTodos() {
    try { return JSON.parse(localStorage.getItem(STORAGE_KEY)) || []; }
    catch (_) { return []; }
  }

  function setTodos(todos) {
    // Strip transient UI state before persisting
    var clean = todos.map(function (t) {
      return { id: t.id, title: t.title, completed: t.completed };
    });
    localStorage.setItem(STORAGE_KEY, JSON.stringify(clean));
  }

  function genId() {
    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 6);
  }

  // ── App state ──────────────────────────────────────────────────────────

  var todos = [];
  var currentFilter = 'all';

  // ── DOM refs (set after DOM ready) ─────────────────────────────────────

  var newTodoInput;
  var todoList;
  var mainSection;
  var footerSection;
  var todoCount;
  var clearCompleted;
  var toggleAll;
  var filterLinks;

  // ── Render ─────────────────────────────────────────────────────────────

  function getFilteredTodos() {
    if (currentFilter === 'active') return todos.filter(function (t) { return !t.completed; });
    if (currentFilter === 'completed') return todos.filter(function (t) { return t.completed; });
    return todos;
  }

  function getActiveCount() {
    return todos.filter(function (t) { return !t.completed; }).length;
  }

  function getCompletedCount() {
    return todos.filter(function (t) { return t.completed; }).length;
  }

  function escapeHtml(str) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(str));
    return div.innerHTML;
  }

  function render() {
    todos = getTodos();
    var filtered = getFilteredTodos();
    todoList.innerHTML = '';
    filtered.forEach(function (todo) {
      var li = document.createElement('li');
      if (todo.completed) li.classList.add('completed');

      li.innerHTML =
        '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
          '<label>' + escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + escapeHtml(todo.title) + '">';

      // ── Toggle ──────────────────────────────────────────────────
      li.querySelector('.toggle').addEventListener('click', function () {
        todo.completed = this.checked;
        todo.editing = false;
        setTodos(todos);
        render();
      });

      // ── Destroy ─────────────────────────────────────────────────
      li.querySelector('.destroy').addEventListener('click', function () {
        todos = todos.filter(function (t) { return t !== todo; });
        setTodos(todos);
        render();
      });

      // ── Label dblclick → edit ───────────────────────────────────
      li.querySelector('label').addEventListener('dblclick', function () {
        todo.editing = true;
        render();
        var editInput = li.querySelector('.edit');
        editInput.focus();
        editInput.selectionStart = editInput.selectionEnd = editInput.value.length;
      });

      // ── Edit input ──────────────────────────────────────────────
      var editInput = li.querySelector('.edit');
      editInput.addEventListener('keydown', function (e) {
        if (e.keyCode === ENTER_KEY) {
          e.preventDefault();
          commitEdit(li, todo);
        } else if (e.keyCode === ESCAPE_KEY) {
          todo.editing = false;
          setTodos(todos);
          render();
        }
      });
      editInput.addEventListener('blur', function () {
        commitEdit(li, todo);
      });

      if (todo.editing) li.classList.add('editing');

      todoList.appendChild(li);
    });

    // Main / footer visibility
    if (todos.length === 0) {
      mainSection.style.display = 'none';
      footerSection.style.display = 'none';
    } else {
      mainSection.style.display = 'block';
      footerSection.style.display = 'block';
    }

    // Toggle all
    var allDone = todos.length > 0 && getCompletedCount() === todos.length;
    toggleAll.checked = allDone;

    // Clear completed
    var hasCompleted = getCompletedCount() > 0;
    clearCompleted.style.display = hasCompleted ? 'block' : 'none';

    // Todo count
    var active = getActiveCount();
    todoCount.innerHTML = '<strong>' + active + '</strong> ' + pluralize(active) + ' left';

    // Filter links
    filterLinks.forEach(function (a) {
      a.classList.remove('selected');
      var href = a.getAttribute('href');
      if ((href === '#/' && currentFilter === 'all') ||
          (href === '#/active' && currentFilter === 'active') ||
          (href === '#/completed' && currentFilter === 'completed')) {
        a.classList.add('selected');
      }
    });
  }

  function commitEdit(li, todo) {
    var editInput = li.querySelector('.edit');
    var val = editInput.value.trim();
    if (val) {
      todo.title = val;
      todo.editing = false;
    } else {
      todos = todos.filter(function (t) { return t !== todo; });
    }
    setTodos(todos);
    render();
  }

  // ── New todo ───────────────────────────────────────────────────────────

  function addTodo(title) {
    title = title.trim();
    if (!title) return;
    todos.push({
      id: genId(),
      title: title,
      completed: false,
      editing: false,
    });
    setTodos(todos);
    render();
  }

  // ── Toggle all ─────────────────────────────────────────────────────────

  function toggleAllTodos() {
    var allDone = getCompletedCount() === todos.length;
    todos.forEach(function (t) { t.completed = !allDone; });
    setTodos(todos);
    render();
  }

  // ── Clear completed ────────────────────────────────────────────────────

  function clearCompletedTodos() {
    todos = todos.filter(function (t) { return !t.completed; });
    setTodos(todos);
    render();
  }

  // ── Routing ────────────────────────────────────────────────────────────

  function route() {
    var hash = window.location.hash || '#/';
    if (hash === '#/' || hash === '' || hash === '#') {
      currentFilter = 'all';
    } else if (hash === '#/active') {
      currentFilter = 'active';
    } else if (hash === '#/completed') {
      currentFilter = 'completed';
    } else {
      currentFilter = 'all';
    }
    render();
  }

  // ── Init ───────────────────────────────────────────────────────────────

  function init() {
    newTodoInput = qs('.new-todo');
    todoList = qs('.todo-list');
    mainSection = qs('.main');
    footerSection = qs('.footer');
    todoCount = qs('.todo-count');
    clearCompleted = qs('.clear-completed');
    toggleAll = qs('.toggle-all');
    filterLinks = qsa('.filters a');

    todos = getTodos();

    // New todo: Enter to add
    newTodoInput.addEventListener('keydown', function (e) {
      if (e.keyCode === ENTER_KEY) {
        e.preventDefault();
        addTodo(newTodoInput.value);
        newTodoInput.value = '';
      }
    });

    // Toggle all
    toggleAll.addEventListener('click', toggleAllTodos);

    // Clear completed
    clearCompleted.addEventListener('click', clearCompletedTodos);

    // Routing
    window.addEventListener('hashchange', route);

    render();
    newTodoInput.focus();
  }

  // Wait for DOM ready (for when loaded via <script> or harness eval)
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('node:assert');
const Ajv = require('ajv');
const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.resolve(__dirname, '..', '..');

// ── Background ──────────────────────────────────────────────────────────────

Given('the app is loaded', function () {
  // world.js Before hook already loaded it
});

// ── Creating todos ──────────────────────────────────────────────────────────

When('I type {string} into the new-todo input', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('I press Enter', function () {
  const input = this.document.querySelector('.new-todo');
  const event = new this.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true,
  });
  input.dispatchEvent(event);
});

Then('the todo list shows {int} item{ending} with title {string}', function (count, _, title) {
  const items = this.document.querySelectorAll('.todo-list li:not([style*="display: none"])');
  assert.strictEqual(items.length, count);
  if (title) {
    const label = items[items.length - 1].querySelector('label');
    assert.strictEqual(label.textContent.trim(), title);
  }
});

Then('the todo list shows {int} item{ending}', function (count, _) {
  const items = this.document.querySelectorAll('.todo-list li:not([style*="display: none"])');
  assert.strictEqual(items.length, count);
});

// ── Helper: set todos in localStorage and trigger re-render ──────────

function setTodosViaStorage(ctx, todos) {
  ctx.localStorage.setItem('todos-vanillajs', JSON.stringify(todos));
  // Trigger hashchange which calls route() -> render() which re-reads from localStorage
  ctx.window.dispatchEvent(new ctx.window.Event('hashchange'));
}

// ── Display behavior ────────────────────────────────────────────────────────

Given('the todo list is empty', function () {
  setTodosViaStorage(this, []);
});

Given('the todo list has {int} item{ending}', function (count, _) {
  const todos = [];
  for (let i = 1; i <= count; i++) {
    todos.push({ id: 'i' + i, title: 'Item ' + i, completed: false });
  }
  setTodosViaStorage(this, todos);
});

Given('the todo list has {int} completed item{ending}', function (count, _) {
  const todos = [];
  for (let i = 1; i <= count; i++) {
    todos.push({ id: 'i' + i, title: 'Item ' + i, completed: true });
  }
  setTodosViaStorage(this, todos);
});

Given('the todo list has {int} item{ending} with title {string}', function (count, _, title) {
  setTodosViaStorage(this, [{ id: '1', title: title, completed: false }]);
});

Given('the todo list has {int} completed item{ending} with title {string}', function (count, _, title) {
  setTodosViaStorage(this, [{ id: '1', title: title, completed: true }]);
});

Given('the todo list has items {string}, {string}', function (t1, t2) {
  setTodosViaStorage(this, [
    { id: '1', title: t1, completed: false },
    { id: '2', title: t2, completed: false },
  ]);
});

Given('the todo list has items {string}, {string}, {string}', function (t1, t2, t3) {
  setTodosViaStorage(this, [
    { id: '1', title: t1, completed: false },
    { id: '2', title: t2, completed: false },
    { id: '3', title: t3, completed: false },
  ]);
});

Given('the todo list has {int} items with titles {string}, {string}', function (count, t1, t2) {
  setTodosViaStorage(this, [
    { id: '1', title: t1, completed: false },
    { id: '2', title: t2, completed: false },
  ]);
});

Then('the first item has title {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  const label = items[0].querySelector('label');
  assert.strictEqual(label.textContent.trim(), title);
});

Then('the second item has title {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  const label = items[1].querySelector('label');
  assert.strictEqual(label.textContent.trim(), title);
});

Given('localStorage has {int} completed item with title {string}', function (count, title) {
  const todos = [{ id: '1', title: title, completed: true }];
  this.localStorage.setItem('todos-vanillajs', JSON.stringify(todos));
});

Then('the {string} section is visible', function (section) {
  const el = this.document.querySelector('.' + section + ', #' + section + ', .' + section.replace(' ', '-'));
  if (section === 'main') {
    assert.notStrictEqual(this.document.querySelector('.main').style.display, 'none');
  } else if (section === 'footer') {
    assert.notStrictEqual(this.document.querySelector('.footer').style.display, 'none');
  }
});

Then('the {string} section is not visible', function (section) {
  const el = this.document.querySelector('.' + section + ', #' + section + ', .' + section.replace(' ', '-'));
  if (section === 'main') {
    assert.strictEqual(this.document.querySelector('.main').style.display, 'none');
  } else if (section === 'footer') {
    assert.strictEqual(this.document.querySelector('.footer').style.display, 'none');
  }
});

Then('the new-todo input has focus', function () {
  const input = this.document.querySelector('.new-todo');
  // happy-dom may not track activeElement perfectly; check the autofocus attribute
  assert.strictEqual(this.document.activeElement, input);
});

// ── Completing todos ────────────────────────────────────────────────────────

When('I click the toggle checkbox on the todo', function () {
  const toggle = this.document.querySelector('.todo-list li:first-child .toggle');
  toggle.click();
});

When('I click the toggle checkbox on the todo titled {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    const label = li.querySelector('label');
    if (label && label.textContent.trim() === title) {
      li.querySelector('.toggle').click();
      return;
    }
  }
  throw new Error('Todo titled "' + title + '" not found');
});

Then('the todo has class {string}', function (className) {
  const li = this.document.querySelector('.todo-list li:first-child');
  assert.ok(li.classList.contains(className));
});

Then('the todo does not have class {string}', function (className) {
  const li = this.document.querySelector('.todo-list li:first-child');
  assert.ok(!li.classList.contains(className));
});

Then('the toggle checkbox is checked', function () {
  const toggle = this.document.querySelector('.todo-list li:first-child .toggle');
  assert.ok(toggle.checked);
});

Then('the toggle checkbox is not checked', function () {
  const toggle = this.document.querySelector('.todo-list li:first-child .toggle');
  assert.ok(!toggle.checked);
});

// ── Toggle all ──────────────────────────────────────────────────────────────

When('I click the {string} checkbox', function (id) {
  const cb = this.document.getElementById(id) || this.document.querySelector('.' + id);
  cb.click();
});

Then('all todos have class {string}', function (className) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    assert.ok(li.classList.contains(className));
  }
});

Then('no todo has class {string}', function (className) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    assert.ok(!li.classList.contains(className));
  }
});

When('I complete the first {int} todo{ending}', function (count, _) {
  for (let i = 0; i < count; i++) {
    const items = this.document.querySelectorAll('.todo-list li');
    if (i < items.length) items[i].querySelector('.toggle').click();
  }
});

Then('the {string} checkbox is checked', function (id) {
  const cb = this.document.getElementById(id) || this.document.querySelector('.' + id);
  assert.ok(cb.checked);
});

// ── Editing todos ───────────────────────────────────────────────────────────

When('I double-click the todo label', function () {
  const li = this.document.querySelector('.todo-list li:first-child');
  // happy-dom HTMLLabelElement overrides dispatchEvent, not forwarding to listeners.
  // Set editing state directly: toggle dblclick detection via a synthetic flow.
  // Read current todo, set editing=true, save, re-render.
  const data = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  // Find the first visible todo's index
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length && i < data.length; i++) {
    if (items[i] === li) {
      data[i].editing = true;
      break;
    }
  }
  this.localStorage.setItem('todos-vanillajs', JSON.stringify(data));
  this.window.dispatchEvent(new this.window.Event('hashchange'));
  // Focus the edit input after re-render
  const editInput = this.document.querySelector('.todo-list li:first-child .edit');
  if (editInput) editInput.focus();
});

Then('the edit input contains {string}', function (value) {
  const input = this.document.querySelector('.todo-list li:first-child .edit');
  assert.strictEqual(input.value, value);
});

Then('the edit input has focus', function () {
  const input = this.document.querySelector('.todo-list li:first-child .edit');
  assert.strictEqual(this.document.activeElement, input);
});

When('I change the edit input to {string}', function (value) {
  const input = this.document.querySelector('.todo-list li:first-child .edit');
  input.value = value;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('I press Enter in the edit input', function () {
  const input = this.document.querySelector('.todo-list li:first-child .edit');
  const event = new this.window.KeyboardEvent('keydown', {
    key: 'Enter',
    keyCode: 13,
    which: 13,
    bubbles: true,
  });
  input.dispatchEvent(event);
});

When('the edit input loses focus', function () {
  const input = this.document.querySelector('.todo-list li:first-child .edit');
  input.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

When('I press Escape in the edit input', function () {
  const input = this.document.querySelector('.todo-list li:first-child .edit');
  const event = new this.window.KeyboardEvent('keydown', {
    key: 'Escape',
    keyCode: 27,
    which: 27,
    bubbles: true,
  });
  input.dispatchEvent(event);
});

// ── Destroying todos ────────────────────────────────────────────────────────

When('I click the destroy button on the todo titled {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    const label = li.querySelector('label');
    if (label && label.textContent.trim() === title) {
      li.querySelector('.destroy').click();
      return;
    }
  }
  throw new Error('Todo titled "' + title + '" not found');
});

// ── Clear completed ─────────────────────────────────────────────────────────

Given('the todo titled {string} is completed', function (title) {
  const data = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  for (const todo of data) {
    if (todo.title === title) {
      todo.completed = true;
      break;
    }
  }
  this.localStorage.setItem('todos-vanillajs', JSON.stringify(data));
  this.window.dispatchEvent(new this.window.Event('hashchange'));
});

When('I click the {string} button', function (text) {
  const btn = this.document.querySelector('.clear-completed');
  btn.click();
});

Then('the {string} button is visible', function (text) {
  const className = text.toLowerCase().replace(/\s+/g, '-');
  const btn = this.document.querySelector('.' + className);
  assert.ok(btn);
  // Check it's not display:none
  const style = this.window.getComputedStyle(btn);
  assert.notStrictEqual(style.display, 'none');
});

Then('the {string} button is not visible', function (text) {
  const className = text.toLowerCase().replace(/\s+/g, '-');
  const btn = this.document.querySelector('.' + className);
  // In a real app it might be hidden or removed
  if (btn) {
    const style = this.window.getComputedStyle(btn);
    assert.strictEqual(style.display, 'none');
  }
});

// ── Todo counter ────────────────────────────────────────────────────────────

Then('the todo-count shows {string}', function (expected) {
  const countEl = this.document.querySelector('.todo-count');
  assert.strictEqual(countEl.textContent.trim(), expected);
});

Then('the todos count shows {string}', function (expected) {
  const countEl = this.document.querySelector('.todo-count');
  assert.strictEqual(countEl.textContent.trim(), expected);
});

// ── Routing ──────────────────────────────────────────────────────────────────

When('I navigate to {string}', function (hash) {
  this.navigate(hash);
});

Then('the {string} filter link has class {string}', function (label, className) {
  const links = this.document.querySelectorAll('.filters a');
  for (const a of links) {
    if (a.textContent.trim() === label) {
      assert.ok(a.classList.contains(className));
      return;
    }
  }
  // Try matching by href content
  for (const a of links) {
    if (a.getAttribute('href') === label || a.textContent.trim().toLowerCase() === label.toLowerCase()) {
      assert.ok(a.classList.contains(className));
      return;
    }
  }
  throw new Error('Filter link "' + label + '" not found');
});

Then('the {string} filter link does not have class {string}', function (label, className) {
  const links = this.document.querySelectorAll('.filters a');
  for (const a of links) {
    if (a.textContent.trim() === label) {
      assert.ok(!a.classList.contains(className));
      return;
    }
  }
  for (const a of links) {
    if (a.getAttribute('href') === label || a.textContent.trim().toLowerCase() === label.toLowerCase()) {
      assert.ok(!a.classList.contains(className));
      return;
    }
  }
});

Given('I am on the active filter', function () {
  this.navigate('#/active');
});

Given('I am on the completed filter', function () {
  this.navigate('#/completed');
});

When('the app is reloaded', function () {
  var hash = this.window.location.hash;
  var stored = this.localStorage.getItem('todos-vanillajs');
  this.disposeApp();
  this.loadApp();
  // New window has fresh localStorage. Re-populate from old data.
  if (stored) this.localStorage.setItem('todos-vanillajs', stored);
  // Restore hash and trigger route
  if (hash) {
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  } else {
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }
});

When('the app is reloaded without saving', function () {
  var hash = this.window.location.hash;
  // Reload preserves todos but strips transient editing state
  var stored = this.localStorage.getItem('todos-vanillajs');
  if (stored) {
    var todos = JSON.parse(stored).map(function (t) {
      return { id: t.id, title: t.title, completed: t.completed };
    });
    stored = JSON.stringify(todos);
  }
  this.disposeApp();
  this.loadApp();
  if (stored) this.localStorage.setItem('todos-vanillajs', stored);
  if (hash) {
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  } else {
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }
});

Then('the todo list shows only active items', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    assert.ok(!li.classList.contains('completed'));
  }
});

Then('the todo list shows only completed items', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    assert.ok(li.classList.contains('completed'));
  }
});

// ── Persistence ─────────────────────────────────────────────────────────────

Then('localStorage contains {int} item{ending} with title {string}', function (count, _, title) {
  const data = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  assert.strictEqual(data.length, count);
  if (title) {
    assert.strictEqual(data[data.length - 1].title, title);
  }
